content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --success-color: #10b981;
  --success-light: #ecfdf5;
  --success-border: #a7f3d0;
  --danger-color: #ef4444;
  --danger-light: #fef2f2;
  --danger-border: #fecaca;
  --bg-gradient: linear-gradient(135deg, #e0f2fe 0%, #f0fdf4 50%, #f8fafc 100%);
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  line-height: 1.6;
  font-weight: 400;
  color: var(--text-main);
  background: var(--bg-gradient);
  min-height: 100vh;
  box-sizing: border-box;
}

*, *::before, *::after {
  box-sizing: inherit;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
}

.app-container {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  padding: 24px 16px 40px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.quiz-box {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border-color);
  padding: 28px 24px;
  width: 100%;
  animation: fadeIn 0.3s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.quiz-header {
  margin-bottom: 24px;
}

.quiz-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #0f172a;
  text-align: center;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.progress-bar-container {
  width: 100%;
  height: 10px;
  background-color: #e2e8f0;
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: 8px;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6 0%, #10b981 100%);
  border-radius: var(--radius-full);
  transition: width 0.4s ease-in-out;
}

.progress-text {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  text-align: right;
}

.question-badge {
  display: inline-block;
  background-color: var(--primary-light);
  color: var(--primary-color);
  font-size: 0.8125rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
  letter-spacing: 0.05em;
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.5;
  color: #1e293b;
  margin-bottom: 24px;
}

.options-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.option-btn {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 52px;
  padding: 12px 18px;
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
  background-color: #f8fafc;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
  touch-action: manipulation;
}

.option-btn:hover:not(:disabled) {
  background-color: var(--primary-light);
  border-color: #93c5fd;
  transform: translateY(-1px);
}

.option-btn:active:not(:disabled) {
  transform: translateY(0);
}

.option-btn:disabled {
  cursor: default;
}

.option-btn-selected {
  border-color: var(--primary-color);
  background-color: var(--primary-light);
  font-weight: 600;
}

.option-btn-correct {
  border-color: var(--success-color);
  background-color: var(--success-light);
  color: #065f46;
  font-weight: 700;
}

.option-btn-wrong {
  border-color: var(--danger-color);
  background-color: var(--danger-light);
  color: #991b1b;
  font-weight: 600;
}

.feedback-card {
  margin-top: 20px;
  padding: 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background-color: #f8fafc;
  animation: fadeIn 0.3s ease;
}

.feedback-status {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.feedback-correct {
  color: #059669;
}

.feedback-wrong {
  color: #dc2626;
}

.feedback-explanation {
  font-size: 0.95rem;
  line-height: 1.6;
  color: #334155;
  margin-bottom: 12px;
}

.trivia-box {
  background-color: #fffbeb;
  border-left: 4px solid #f59e0b;
  padding: 10px 14px;
  border-radius: 4px;
  font-size: 0.875rem;
  color: #92400e;
  line-height: 1.5;
  margin-top: 8px;
}

.next-btn {
  display: block;
  width: 100%;
  margin-top: 20px;
  padding: 14px;
  background-color: var(--primary-color);
  color: #ffffff;
  font-size: 1.05rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: all 0.2s ease;
  text-align: center;
  user-select: none;
}

.next-btn:hover {
  background-color: var(--primary-hover);
  transform: translateY(-1px);
}

.next-btn:active {
  transform: translateY(0);
}

/* 結果カード */
.result-card {
  text-align: center;
  animation: fadeIn 0.4s ease;
}

.score-circle {
  width: 130px;
  height: 130px;
  margin: 16px auto 20px;
  border-radius: 50%;
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border: 4px solid var(--primary-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  box-shadow: var(--shadow-md);
}

.score-number {
  font-size: 2.75rem;
  font-weight: 800;
  line-height: 1;
  color: var(--primary-color);
}

.score-total {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-top: 4px;
}

.result-message {
  font-size: 1.25rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 24px;
  line-height: 1.5;
}

.review-list {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 28px;
}

.review-item {
  padding: 16px;
  border-radius: var(--radius-md);
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
}

.review-q {
  font-weight: 700;
  font-size: 0.95rem;
  color: #1e293b;
  margin-bottom: 8px;
}

.review-ans {
  font-size: 0.875rem;
  color: #475569;
  line-height: 1.5;
}

.retry-btn {
  display: block;
  width: 100%;
  padding: 14px;
  background-color: var(--primary-color);
  color: #ffffff;
  font-size: 1.05rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: all 0.2s ease;
  user-select: none;
}

.retry-btn:hover {
  background-color: var(--primary-hover);
  transform: translateY(-1px);
}

.retry-btn:active {
  transform: translateY(0);
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px 10px 24px;
  }

  .quiz-box {
    padding: 20px 16px;
    border-radius: var(--radius-md);
  }

  .quiz-title {
    font-size: 1.3rem;
  }

  .question-text {
    font-size: 1.1rem;
    margin-bottom: 18px;
  }

  .option-btn {
    min-height: 48px;
    padding: 10px 14px;
    font-size: 0.95rem;
  }

  .score-circle {
    width: 110px;
    height: 110px;
  }

  .score-number {
    font-size: 2.25rem;
  }
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  answerIndex: number;
  explanation: string;
  trivia: string;
}

export interface UserAnswer {
  questionId: number;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface QuizProgress {
  currentIndex: number;
  score: number;
  isFinished: boolean;
  answers: UserAnswer[];
}

