import { QuizQuestion } from '../types';

interface QuizCardProps {
  question: QuizQuestion;
  selectedIndex: number | null;
  onSelectOption: (index: number) => void;
  onNext: () => void;
  isLastQuestion: boolean;
}

const QuizCard = ({
  question,
  selectedIndex,
  onSelectOption,
  onNext,
  isLastQuestion
}: QuizCardProps) => {
  const isAnswered = selectedIndex !== null;
  const isCorrect = isAnswered && selectedIndex === question.answerIndex;

  const getOptionClassName = (index: number): string => {
    if (!isAnswered) {
      return 'option-btn';
    }
    if (index === question.answerIndex) {
      return 'option-btn option-btn-correct';
    }
    if (index === selectedIndex) {
      return 'option-btn option-btn-wrong';
    }
    return 'option-btn';
  };

  return (
    <div>
      <span className="question-badge">第 {question.id} 問</span>
      <h2 className="question-text">{question.question}</h2>

      <div className="options-grid">
        {question.options.map((option, index) => (
          <button
            key={index}
            type="button"
            className={getOptionClassName(index)}
            onClick={() => onSelectOption(index)}
            disabled={isAnswered}
          >
            {index + 1}. {option}
          </button>
        ))}
      </div>

      {isAnswered && (
        <div className="feedback-card">
          <div
            className={`feedback-status ${
              isCorrect ? 'feedback-correct' : 'feedback-wrong'
            }`}
          >
            {isCorrect ? '⭕ 正解！' : '❌ 残念、不正解...'}
          </div>
          <p className="feedback-explanation">{question.explanation}</p>
          <div className="trivia-box">
            💡 <strong>豆知識:</strong> {question.trivia}
          </div>
          <button type="button" className="next-btn" onClick={onNext}>
            {isLastQuestion ? '結果を見る' : '次の問題へ'}
          </button>
        </div>
      )}
    </div>
  );
};

export default QuizCard;

import { QuizQuestion, UserAnswer } from '../types';

interface ResultCardProps {
  score: number;
  total: number;
  answers?: UserAnswer[];
  questions?: QuizQuestion[];
  onRetry?: () => void;
}

const ResultCard = ({
  score,
  total,
  answers = [],
  questions = [],
  onRetry
}: ResultCardProps) => {
  const getResultMessage = (score: number, total: number): string => {
    const percentage = (score / total) * 100;
    if (percentage === 100) {
      return '素晴らしい！全問正解の日本地理マスターです！🗺️✨';
    }
    if (percentage >= 80) {
      return 'お見事！かなりの日本地理通ですね！🗾👍';
    }
    if (percentage >= 60) {
      return '合格ライン！あと一歩で満点を目指せます！📗';
    }
    return 'お疲れ様でした！もう一度復習して再挑戦してみましょう！💪';
  };

  const handleRetry = () => {
    onRetry?.();
  };

  return (
    <div className="result-card">
      <h2 className="quiz-title">🏆 クイズ結果発表</h2>

      <div className="score-circle">
        <span className="score-number">{score}</span>
        <span className="score-total">/ {total} 問正解</span>
      </div>

      <p className="result-message">{getResultMessage(score, total)}</p>

      <div className="review-list">
        {questions.map((question, index) => {
          const userAnswer = answers.find(
            (ans) => ans.questionId === question.id
          );
          const isCorrect = userAnswer ? userAnswer.isCorrect : false;
          const userSelectedOption =
            userAnswer && userAnswer.selectedIndex >= 0
              ? question.options[userAnswer.selectedIndex]
              : '未回答';
          const correctOption = question.options[question.answerIndex];

          return (
            <div key={question.id} className="review-item">
              <div className="review-q">
                <span>{isCorrect ? '⭕' : '❌'} </span>
                第{index + 1}問: {question.question}
              </div>
              <div className="review-ans">
                <div>
                  <strong>あなたの回答:</strong> {userSelectedOption}
                  {!isCorrect && (
                    <span style={{ marginLeft: '8px', color: '#059669' }}>
                      (正解: {correctOption})
                    </span>
                  )}
                </div>
                <div style={{ marginTop: '6px' }}>
                  <strong>解説:</strong> {question.explanation}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <button type="button" className="retry-btn" onClick={handleRetry}>
        もう一度挑戦する
      </button>
    </div>
  );
};

export default ResultCard;

import { useState } from 'react';
import { quizQuestions } from './data/quizData';
import { UserAnswer } from './types';
import QuizCard from './components/QuizCard';
import ResultCard from './components/ResultCard';

const App = () => {
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [answers, setAnswers] = useState<UserAnswer[]>([]);
  const [isFinished, setIsFinished] = useState<boolean>(false);

  const totalQuestions = quizQuestions.length;
  const currentQuestion = quizQuestions[currentIndex];

  const handleSelectOption = (index: number) => {
    if (selectedIndex !== null) return;

    setSelectedIndex(index);
    const isCorrect = index === currentQuestion.answerIndex;
    const newAnswer: UserAnswer = {
      questionId: currentQuestion.id,
      selectedIndex: index,
      isCorrect
    };

    setAnswers((prev) => [...prev, newAnswer]);
  };

  const handleNext = () => {
    if (currentIndex + 1 < totalQuestions) {
      setCurrentIndex((prev) => prev + 1);
      setSelectedIndex(null);
    } else {
      setIsFinished(true);
    }
  };

  const handleRetry = () => {
    setCurrentIndex(0);
    setSelectedIndex(null);
    setAnswers([]);
    setIsFinished(false);
  };

  const score = answers.filter((a) => a.isCorrect).length;
  const progressPercentage = isFinished
    ? 100
    : Math.round(((currentIndex + (selectedIndex !== null ? 1 : 0)) / totalQuestions) * 100);

  return (
    <div className="app-container">
      <div className="quiz-box">
        <header className="quiz-header">
          <h1 className="quiz-title">🗾 日本地理クイズチャレンジ</h1>
          <div className="progress-bar-container">
            <div
              className="progress-bar-fill"
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
          <div className="progress-text">
            {isFinished
              ? '全問終了'
              : `進行状況: ${currentIndex + 1} / ${totalQuestions}`}
          </div>
        </header>

        {isFinished ? (
          <ResultCard
            score={score}
            total={totalQuestions}
            answers={answers}
            questions={quizQuestions}
            onRetry={handleRetry}
          />
        ) : (
          <QuizCard
            question={currentQuestion}
            selectedIndex={selectedIndex}
            onSelectOption={handleSelectOption}
            onNext={handleNext}
            isLastQuestion={currentIndex === totalQuestions - 1}
          />
        )}
      </div>
    </div>
  );
};

export default App;
